import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Review, approval and publication","description":"","frontmatter":{},"headers":[],"relativePath":"websites/publication-controls.md","filePath":"websites/publication-controls.md"}'),r={name:"websites/publication-controls.md"};function n(s,e,l,d,p,c){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="review-approval-and-publication" tabindex="-1">Review, approval and publication <a class="header-anchor" href="#review-approval-and-publication" aria-label="Permalink to &quot;Review, approval and publication&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release — source-reviewed draft</p><p>TransferBook+ v0.7.9 source baseline. Availability depends on installed release, permissions and configuration. Live publication is not established by this guide.</p></div><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Distinguish visual readiness from operational publication. This guide describes the Template Manager source workflow, not permission to publish a live site.</p><h2 id="review-lifecycle" tabindex="-1">Review lifecycle <a class="header-anchor" href="#review-lifecycle" aria-label="Permalink to &quot;Review lifecycle&quot;">​</a></h2><ol><li>Start with a validated draft assigned to an authorized channel.</li><li>Review its preview, content, localization, device layout and booking form behavior.</li><li>Where supported, use <strong>Mark Preview → Submit for Review → Approve Draft</strong>. Record the review note if appropriate.</li><li>Stop at approval unless publication is separately enabled and authorized. The reference source describes locked Publish and Connect Domain controls.</li></ol><h2 id="what-approval-does-not-do" tabindex="-1">What approval does not do <a class="header-anchor" href="#what-approval-does-not-do" aria-label="Permalink to &quot;What approval does not do&quot;">​</a></h2><p>An approved design does not prove public domain routing, SSL, live reservation capture, payment processing or outbound messaging. These need their own acceptance checks. A restored earlier revision is a new draft, not an automatic public rollback.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If publishing is locked, do not bypass the control. Confirm permissions and the approved deployment policy with the responsible administrator. Keep the draft and an export. See <a href="./template-manager.html">Template Manager</a>.</p><h2 id="restricted-hosting-and-site-operations-in-v0-7-11" tabindex="-1">Restricted hosting and site operations in v0.7.11 <a class="header-anchor" href="#restricted-hosting-and-site-operations-in-v0-7-11" aria-label="Permalink to &quot;Restricted hosting and site operations in v0.7.11&quot;">​</a></h2><p><strong>Status: source-reviewed staging release; disabled by default.</strong> This is a separate Website Studio workflow for a configured demonstration destination, not the general Template Manager publication lifecycle above. Availability requires the matching installed release, separately enabled capabilities, the configured company administrator and website-write permission. The standalone design kit does not provide hosting operations.</p><h3 id="review-and-prepare-a-candidate" tabindex="-1">Review and prepare a candidate <a class="header-anchor" href="#review-and-prepare-a-candidate" aria-label="Permalink to &quot;Review and prepare a candidate&quot;">​</a></h3><ol><li>Inspect hosting status and HTTPS through the authorized hosting panel. A successful check does not authorize a write or establish booking availability.</li><li>Save the selected design. Use <strong>Prepare Website Update</strong> only when authorized and available. Preparation compiles the selected design privately, records its exact fingerprint, rendering warnings and file changes, and creates verified before/after revision snapshots. It does not change public files.</li><li>Review the candidate visually and inspect warnings. The static renderer supports a limited section and asset set; some editor details may be omitted or rejected. Verify navigation and layouts before requesting approval.</li></ol><h3 id="update-or-rollback" tabindex="-1">Update or rollback <a class="header-anchor" href="#update-or-rollback" aria-label="Permalink to &quot;Update or rollback&quot;">​</a></h3><ol start="4"><li>The owner independently reviews the exact revision and authorizes the specific operation. Confirm only the reviewed operation. Update and rollback require distinct, single-use approvals; a rollback is not an automatic consequence of editing a draft.</li><li>After an authorized operation, confirm the intended content and trusted HTTPS. If the result is unknown, do not retry or reuse approval. Escalate for inspection of revision fingerprints, transaction records and recovery snapshots before any further action.</li></ol><p>No unrestricted production publishing, DNS/SSL changes, database migrations, live booking or payment activation are established by this release. If a control is missing or locked, keep the exported design and consult the authorized administrator. See <a href="/release-notes/">release notes</a>.</p>',17)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
